    // 5. Siluet Detail 2
    createFrame({ x: 16, y: 82, width: 75, height: 6, radius: 3, bg: "#E2E8F0", parent: cardKtp });

    // Sisi Kanan: Kotak Pas Foto Siluet (Tanpa Teks)
    var photoCard = createFrame({
      name: "Siluet Pas Foto", x: 202, y: 25, width: 62, height: 84, radius: 8, bg: "#F1F5F9",
      border: { color: "#E2E8F0", width: 1 }, parent: cardKtp
    });
    // Lingkaran Avatar Siluet
    var avCircle = createFrame({ x: 15, y: 26, width: 32, height: 32, radius: 16, bg: "#E2E8F0", parent: photoCard });
    createSvg({ svg: `<svg width="22" height="22" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="8" r="4" fill="#94A3B8"/><path d="M5 20v-1a7 7 0 0114 0v1" fill="#94A3B8"/></svg>`, x: 5, y: 5, width: 22, height: 22, parent: avCircle });

