    createSvg({ svg: cornerSvg(0), x: 8, y: 8, width: 34, height: 34, parent: reticle });
    createSvg({ svg: cornerSvg(90), x: 228, y: 8, width: 34, height: 34, parent: reticle });
    createSvg({ svg: cornerSvg(270), x: 8, y: 228, width: 34, height: 34, parent: reticle });
