    createText({ text: "Galeri", x: 210, y: 618, width: 80, fontSize: 11, color: "#FFFFFF", opacity: 0.85, align: "center", parent: f });

    var outerShutter = createFrame({
      name: "Outer Shutter", x: 159, y: 660, width: 72, height: 72, radius: 36, bg: "#0F172A",
      border: { color: "#00BFA5", width: 3.5 }, parent: f
    });
